-- Db2 column options for CREATE TABLE.
-- https://www.ibm.com/docs/en/db2/11.5?topic=statements-create-table

CREATE TABLE t_defaults (
    a INT WITH DEFAULT 0,
    b INT DEFAULT NULL,
    c TIMESTAMP DEFAULT CURRENT TIMESTAMP,
    d VARCHAR(10) DEFAULT 'x'
);

CREATE TABLE t_lob_options (
    a CLOB INLINE LENGTH 100,
    b BLOB NOT LOGGED NOT COMPACT,
    c DBCLOB LOGGED COMPACT,
    d CLOB LOGGED
);

CREATE TABLE t_constraint_attributes (
    a INT CONSTRAINT pk PRIMARY KEY ENFORCED,
    b INT UNIQUE NOT ENFORCED,
    c INT REFERENCES p (id) TRUSTED,
    d INT CHECK (d > 0) NOT TRUSTED DISABLE QUERY OPTIMIZATION
);

CREATE TABLE t_column_options (
    a INT COMPRESS SYSTEM DEFAULT,
    b INT NOT HIDDEN,
    c INT IMPLICITLY HIDDEN,
    d INT COLUMN SECURED WITH lbl,
    e INT SECURED WITH lbl
);

CREATE TABLE t_ref_scope (
    a REF(my_type) SCOPE my_table
);

CREATE TABLE t_generated_timestamps (
    a TIMESTAMP GENERATED ALWAYS FOR EACH ROW ON UPDATE AS ROW CHANGE TIMESTAMP,
    b TIMESTAMP GENERATED ALWAYS AS ROW BEGIN,
    c TIMESTAMP GENERATED ALWAYS AS ROW END,
    d TIMESTAMP GENERATED ALWAYS AS TRANSACTION START ID
);

CREATE TABLE t_period (
    a TIMESTAMP(12) GENERATED ALWAYS AS ROW BEGIN,
    b TIMESTAMP(12) GENERATED ALWAYS AS ROW END,
    PERIOD SYSTEM_TIME (a, b)
);
